// Generated by scripts/derive-benchmark-frametimes.js from the published raw captures.
import frametimes from '../../../docs/benchmark-frametimes.json' with { type: 'json' };

export const profiles = [
	{ id: 'stock', label: 'Default Windows' },
	{ id: 'optimized', label: 'SoftheOS + BIOS' },
];

export const { exceedance, runs } = frametimes;

const median = (values) => {
	const sorted = [...values].sort((a, b) => a - b);
	const middle = Math.floor(sorted.length / 2);
	return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
};

/**
 * Median across a profile's runs, taken in FPS like the published figures, so the 1% point
 * reproduces the reported P1 FPS median exactly (a median of frame times would not).
 */
export const profileFrameTime = (profile, index) => 1000 / median(runs.filter((run) => run.profile === profile).map((run) => 1000 / run.frameTimeMs[index]));

export const frameRange = runs.reduce((range, run) => [Math.min(range[0], ...run.frameTimeMs), Math.max(range[1], ...run.frameTimeMs)], [Infinity, 0]);

export const framesPerRun = runs.map((run) => run.frames);

// The rows a reader most often asks about; 0.01 is where P1 FPS is read.
export const percentileRows = [
	{ share: 0.5, label: 'Median frame', detail: 'Half of frames were slower' },
	{ share: 0.1, label: '90th percentile', detail: '1 in 10 frames was slower' },
	{ share: 0.01, label: '99th percentile (P1 FPS)', detail: '1 in 100 frames was slower' },
	{ share: 0.001, label: '99.9th percentile', detail: '1 in 1,000 frames was slower' },
].map((row) => {
	const index = exceedance.indexOf(row.share);
	if (index === -1) throw new Error(`Frame-time data has no ${row.share} exceedance point`);
	return { ...row, index, values: Object.fromEntries(profiles.map(({ id }) => [id, profileFrameTime(id, index)])) };
});
